144			)
145			SELECT id, uid
146			FROM memo_tree
147		`, userID)
148		if err != nil {
149			return nil, err
150		}
151		defer rows.Close()
152	
153		memos := make([]deleteUserMemoRef, 0)
154		for rows.Next() {
155			var memo deleteUserMemoRef
156			if err := rows.Scan(&memo.ID, &memo.UID); err != nil {
157				return nil, err
158			}
159			memos = append(memos, memo)
160		}
161		if err := rows.Err(); err != nil {
162			return nil, err
163		}
164	
165		return memos, nil
